<script setup lang="ts">
import type { RouteWaypoint } from '@sky/routes'
const props = defineProps<{ points: RouteWaypoint[]; selected: number; disabled: boolean; mode: string; reason: string }>()
const emit = defineEmits<{ select: [index: number]; mode: [mode: 'navigate' | 'add' | 'move']; update: [index: number, point: RouteWaypoint]; remove: [index: number]; reorder: [index: number, direction: number]; reason: [value: string]; clear: [] }>()
function change(index: number, key: keyof RouteWaypoint, event: Event) { emit('update', index, { ...props.points[index]!, [key]: Number((event.target as HTMLInputElement).value) }) }
</script>
<template>
  <section class="panel"><h2>航点编辑 · 起终点固定</h2><div class="actions"><el-button :disabled="disabled" :type="mode === 'navigate' ? 'primary' : 'default'" @click="emit('mode', 'navigate')">浏览地图</el-button><el-button :disabled="disabled || points.length >= 24" :type="mode === 'add' ? 'primary' : 'default'" @click="emit('mode', 'add')">点击地图添加航点</el-button><el-button :disabled="disabled || selected < 0" :type="mode === 'move' ? 'primary' : 'default'" @click="emit('mode', 'move')">点击地图移动选中航点</el-button><el-button :disabled="disabled || !points.length" @click="emit('clear')">清空中间航点</el-button></div>
    <p>当前 {{ points.length }}/24 个航点。选点平面位于任务巡航高度，不是楼顶或地形拾取；拖动仍用于旋转地图，单击完成添加/移动。黄色为未校验草稿，不能据此判断安全。切换任务会丢弃未保存草稿。</p>
    <div class="table-wrap"><table><thead><tr><th>序号</th><th>经度 WGS84</th><th>纬度 WGS84</th><th>编辑</th></tr></thead><tbody><tr v-for="(p, i) in points" :key="i" :class="{ selected: i === selected }"><td>{{ i + 1 }}</td><td><input :aria-label="`航点${i + 1}经度`" :value="p.longitude" type="number" min="-180" max="180" step="0.000001" :disabled="disabled" @change="change(i, 'longitude', $event)" /></td><td><input :aria-label="`航点${i + 1}纬度`" :value="p.latitude" type="number" min="-90" max="90" step="0.000001" :disabled="disabled" @change="change(i, 'latitude', $event)" /></td><td><el-button :disabled="disabled" @click="emit('select', i)">选中</el-button><el-button :disabled="disabled || i === 0" @click="emit('reorder', i, -1)">上移</el-button><el-button :disabled="disabled || i === points.length - 1" @click="emit('reorder', i, 1)">下移</el-button><el-button :disabled="disabled" @click="emit('remove', i)">删除</el-button></td></tr><tr v-if="!points.length"><td colspan="4">暂无中间航点；选择“点击地图添加航点”，在地图上单击。</td></tr></tbody></table></div>
    <label class="reason">规划原因<input aria-label="航线规划原因" :value="reason" :disabled="disabled" maxlength="500" @input="emit('reason', ($event.target as HTMLInputElement).value)" /></label>
  </section>
</template>
<style scoped>.panel { padding:18px; background:#0b1d2d; border:1px solid #21445b; }.panel h2 { margin:0 0 14px; font-size:16px; }.panel p { font-size:12px; line-height:1.8; color:#a6bfd0; }.actions { display:flex; gap:8px; flex-wrap:wrap; }.actions :deep(.el-button) { margin:0; }.table-wrap { overflow:auto; }table { border-collapse:collapse; width:100%; font-size:12px; }th,td { text-align:left; padding:10px; border-bottom:1px solid #21445b; }input { background:#102a3d; color:#d8effa; border:1px solid #31546b; padding:8px; border-radius:4px; }td input { width:155px; }.selected { background:#173a4c; }.reason { display:grid; gap:8px; font-size:12px; color:#a6bfd0; margin-top:16px; }</style>
